using Dapper;using Valora.Application.ActionCenter;using Valora.Application.Contracts;
namespace Valora.Infrastructure.Repositories;public sealed class RecommendationRepository(IDbConnectionFactory db):IRecommendationRepository{public async Task<IReadOnlyList<ActionRecommendationDto>>List(Guid o,CancellationToken c){using var x=db.Create();return(await x.QueryAsync<ActionRecommendationDto>(new CommandDefinition("SELECT id,source_type SourceType,source_id SourceId,observation,evidence,correlation,impact,priority,recommendation,limitation,status FROM valorapesquisa.recommendation_queue WHERE organization_id=@o AND deleted_at IS NULL ORDER BY created_at DESC",new{o},cancellationToken:c))).ToList();}public async Task<Guid>Enqueue(Guid o,Guid u,ActionRecommendationDto r,CancellationToken c){var id=Guid.NewGuid();using var x=db.Create();await x.ExecuteAsync(new CommandDefinition("INSERT INTO valorapesquisa.recommendation_queue(id,organization_id,source_type,source_id,observation,evidence,correlation,impact,priority,recommendation,limitation,status,created_by_user_id) VALUES(@id,@o,@SourceType,@SourceId,@Observation,@Evidence,@Correlation,@Impact,@Priority,@Recommendation,@Limitation,'proposed',@u)",new{id,o,u,r.SourceType,r.SourceId,r.Observation,r.Evidence,r.Correlation,r.Impact,r.Priority,r.Recommendation,r.Limitation},cancellationToken:c));return id;}}
